2408	                                                        *i = if *i == 0 {
2409	                                                            len.saturating_sub(1)
2410	                                                        } else {
2411	                                                            *i - 1
2412	                                                        }
2413	                                                    });
2414	                                                    return;
2415	                                                }
2416	                                                "Enter" | "Tab" => {
2417	                                                    ev.prevent_default();
