    view! {
        <div class="voice-plan__brief">
            <h3>{brief.title}</h3>
            <section><h4>"Problem"</h4><p>{brief.problem}</p></section>
            {sections.into_iter().map(|(heading, values)| view! {
                <section>
                    <h4>{heading}</h4>
                    <ul>{values.into_iter().map(|value| view! { <li>{value}</li> }).collect_view()}</ul>
                </section>
            }).collect_view()}
        </div>
    }
}

